    vdl = EXCLUDED.vdl,
    updated_at = TIMEZONE('utc', NOW());

-- ------------------------------------------------------------------------------
-- 4. CREATE JUNCTION TABLE: nepal_aircraft_specifications
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.nepal_aircraft_specifications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nepal_aircraft_id BIGINT NOT NULL REFERENCES public.nepal_aircraft(id) ON DELETE CASCADE,
    specification_id BIGINT NOT NULL REFERENCES public.aircraft_specifications(id) ON DELETE CASCADE,
    match_method VARCHAR(50) DEFAULT 'typecode_match' NOT NULL, -- 'exact_typecode', 'model_variant', 'iata_mapping'
    match_confidence NUMERIC(3, 2) DEFAULT 1.00 NOT NULL,       -- Confidence score (0.00 - 1.00)
    is_primary BOOLEAN DEFAULT TRUE NOT NULL,                   -- Primary specification baseline
    notes TEXT,                                                 -- Detailed mapping / variant notes
    created_at TIMESTAMPTZ DEFAULT TIMEZONE('utc', NOW()) NOT NULL,
    CONSTRAINT uq_nepal_aircraft_specification UNIQUE (nepal_aircraft_id, specification_id)
);

-- Indexes for junction lookups
CREATE INDEX IF NOT EXISTS idx_nas_nepal_aircraft_id ON public.nepal_aircraft_specifications (nepal_aircraft_id);
CREATE INDEX IF NOT EXISTS idx_nas_specification_id ON public.nepal_aircraft_specifications (specification_id);
CREATE INDEX IF NOT EXISTS idx_nas_composite ON public.nepal_aircraft_specifications (nepal_aircraft_id, specification_id);

-- ------------------------------------------------------------------------------
-- 5. AUTOMATICALLY POPULATE JUNCTION TABLE LINKS
-- ------------------------------------------------------------------------------
INSERT INTO public.nepal_aircraft_specifications (
    nepal_aircraft_id, specification_id, match_method, match_confidence, is_primary, notes
)
SELECT 
    na.id AS nepal_aircraft_id,
    s.id AS specification_id,
    CASE 
        WHEN UPPER(s.icao_type) = UPPER(na.typecode) THEN 'exact_typecode'
        WHEN UPPER(s.icao_type) = 'DH4' AND na.typecode = 'DH8D' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = 'J41' AND na.typecode = 'JS41' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = 'CR2' AND na.typecode = 'CRJ2' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = 'CR7' AND na.typecode = 'CRJ7' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = '320' AND na.typecode = 'A320' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = '319' AND na.typecode = 'A319' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = '332' AND na.typecode = 'A332' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = '752' AND na.typecode = 'B752' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = 'BE1' AND na.typecode = 'B190' THEN 'iata_mapping'
        WHEN UPPER(s.icao_type) = 'D28' AND na.typecode IN ('D228', 'D28D') THEN 'iata_mapping'
        ELSE 'model_variant'
    END AS match_method,
    1.00 AS match_confidence,
    CASE
        WHEN s.model IN ('ATR72-500Basic', 'BombardierQ400', 'Jetstream41', 'DHC-6-400 Twin Otter', 'A320-200', '757-200', 'A330-200', 'BombardierCRJ200ER', 'BombardierCRJ700', 'Beech1900D', 'Dornier228-212', 'Let L-410 Turbolet', 'Airbus Helicopters H125 / AS350 B3', 'Bell 407GXP', 'Bell 505 Jet Ranger X', 'Leonardo AW139', 'ATR42-320Basic', 'A319-100') THEN TRUE
        ELSE FALSE
    END AS is_primary,
    CONCAT('Matched tail ', na.registration, ' (typecode: ', na.typecode, ') with spec ', s.model, ' [', s.icao_type, ']') AS notes
FROM public.nepal_aircraft na
JOIN public.aircraft_specifications s ON (
    -- 1. Exact ICAO code match
    UPPER(s.icao_type) = UPPER(na.typecode)
    -- 2. Precision model variant matching for Nepal carriers
    OR (na.typecode = 'AT75' AND s.model IN ('ATR72-500Basic', 'ATR72-500IncreasedWeight', 'ATR 72-500'))
    OR (na.typecode = 'AT43' AND s.model IN ('ATR42-320Basic', 'ATR42-320IncreasedWeight', 'ATR 42-320'))
    OR (na.typecode = 'DH8D' AND (s.icao_type = 'DH4' OR s.model ILIKE '%Q400%'))
    OR (na.typecode = 'JS41' AND (s.icao_type = 'J41' OR s.model ILIKE '%Jetstream41%'))
    OR (na.typecode = 'CRJ2' AND (s.icao_type = 'CR2' OR s.model ILIKE '%CRJ200%'))
    OR (na.typecode = 'CRJ7' AND (s.icao_type = 'CR7' OR s.model ILIKE '%CRJ700%'))
    OR (na.typecode = 'A320' AND (s.model IN ('A320-200', 'A320-200neo') OR s.icao_type = '320'))
    OR (na.typecode = 'A319' AND (s.model ILIKE '%A319%' OR s.icao_type = '319'))
    OR (na.typecode = 'A332' AND (s.model ILIKE '%A330-200%' OR s.icao_type = '332'))
    OR (na.typecode = 'B752' AND (s.model ILIKE '%757-200%' OR s.icao_type = '752'))
    OR (na.typecode = 'B190' AND (s.model ILIKE '%1900D%' OR s.icao_type = 'BE1'))
    OR (na.typecode IN ('D228', 'D28D') AND (s.model ILIKE '%228%' OR s.icao_type = 'D28'))
)
ON CONFLICT (nepal_aircraft_id, specification_id) DO NOTHING;

-- ------------------------------------------------------------------------------
-- 6. ROW LEVEL SECURITY (RLS) POLICIES
-- ------------------------------------------------------------------------------
ALTER TABLE public.nepal_aircraft ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.nepal_aircraft_specifications ENABLE ROW LEVEL SECURITY;

DO $$ 
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'nepal_aircraft' AND policyname = 'Allow public read on nepal_aircraft'
    ) THEN
        CREATE POLICY "Allow public read on nepal_aircraft" ON public.nepal_aircraft FOR SELECT USING (true);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'nepal_aircraft_specifications' AND policyname = 'Allow public read on nepal_aircraft_specifications'
    ) THEN
        CREATE POLICY "Allow public read on nepal_aircraft_specifications" ON public.nepal_aircraft_specifications FOR SELECT USING (true);
    END IF;
END $$;
